{"type":"user","message":{"role":"user","content":[{"tool_use_id":"toolu_01ApXQX9Mra4hzn2QGDmiTgx","type":"tool_result","content":"75	export function renderManagedHostRunDoctorSection(
76	  managedHostRuns: ManagedHostRunRuntimeScan,
77	  managedHostRunGc: ManagedHostRunGcResult | null = null,
78	  brief = false,
79	): string[] {
80	  const lines = ['Managed host runs:'];
81	  lines.push(
82	    `  active=${managedHostRuns.active} terminal=${managedHostRuns.terminal} corrupt=${managedHostRuns.corrupt} `
83	    + `gcEligible=${managedHostRuns.eligibleForGc} retentionMs=${managedHostRuns.retentionMs}`,
84	  );
85	  if (!brief) {
86	    for (const run of managedHostRuns.runs) {
87	      lines.push(
88	        `  - ${run.runId} state=${run.state} worker=${run.workerLiveness} `
89	        + `heartbeatAt=${run.workerHeartbeatAt ?? 'none'} providerProgress=${run.providerProgressMode}:${run.lastProviderProgressAt ?? 'none'} `
90	        + `deadlineAt=${run.deadlineAt ?? 'unknown'} cancelAt=${run.cancelRequestedAt ?? 'none'} `
91	        + `residual=${run.residualProcessGroup ?? 'unknown'} replacementSafe=${run.replacementSafe ?? 'unknown'} `
92	        + `terminalReason=${run.terminalReason ?? 'none'} retentionExpired=${run.retentionExpired} oneShotInputs=${run.hasUnconsumedOneShotInputs}`,
93	      );
94	      if (run.error) lines.push(`    error: ${run.error}`);
95	    }
96	  }
97	  if (managedHostRunGc) {
98	    for (const runId of managedHostRunGc.removed) lines.push(`  ✓ removed expired terminal run ${runId}`);
99	    for (const runId of managedHostRunGc.archivedReceipts) lines.push(`  ✓ preserved sealed receipt archive ${runId}`);
100	    for (const failed of managedHostRunGc.failed) lines.push(`  ✗ failed to remove ${failed.runId}: ${failed.error}`);
101	  } else if (managedHostRuns.eligibleForGc > 0) {
102	    lines.push('  → Run lattice doctor --repair to remove only terminal runs beyond retention; active/corrupt/one-shot-input runs stay protected.');
103	  }
104	  lines.push('');
105	  return lines;
106	}
